  <header class="hub-header"><div><span class="hub-breadcrumb">TETRIS BATTLE <i>/</i> {{ screen==='lobby'?'함께하기':screen==='help'?'가이드':localTab==='stuff'?'나의 기록':'플레이' }}</span><h1>{{ screen==='lobby'?'친구와 연결':screen==='help'?'플레이 가이드':localTab==='stuff'?'나의 플레이 기록':'오늘도, 즐거운 한 판.' }}</h1></div><button class="hub-settings" aria-label="조작 설정" @click="emit('settings')"><HubIcon name="settings"/><span>설정</span></button></header>
  <section v-if="localTab==='stuff'&&(screen==='menu'||screen==='modes')" class="hub-records"><div class="hub-profile-strip"><span class="hub-avatar">{{ (playerName||'P').slice(0,1).toUpperCase() }}</span><div><h2>{{ playerName||'PLAYER 1' }}</h2><p>이 기기에 쌓아 온 나의 플레이</p></div><button @click="emit('profiles')">프로필 편집 <HubIcon name="arrow"/></button></div><div class="hub-stats"><div><small>플레이한 경기</small><strong>{{ totalGames }}<span>판</span></strong></div><div><small>통산 승리</small><strong>{{ totalWins }}<span>승</span></strong></div><div><small>최고 점수</small><strong>{{ bestScore.toLocaleString() }}</strong></div></div><section class="hub-record-table"><h2>모드별 베스트</h2><article v-for="mode in orderedModes" :key="mode.id"><span class="hub-record-icon" :class="mode.id"><HubIcon :name="mode.id==='item'?'spark':mode.id==='speed'?'bolt':'blocks'"/></span><div><strong>{{ mode.name }}</strong><small>{{ history.records[mode.id]?.games||0 }}판 플레이</small></div><b>{{ history.records[mode.id]?.bestScore.toLocaleString()||'0' }}<small>최고 점수</small></b><b>{{ history.records[mode.id]?.wins||0 }}<small>승리</small></b></article><p>같은 맥 2P의 기록은 1P 기준으로 저장됩니다.</p></section><section class="hub-maps-card"><h2>맵 둘러보기</h2><p>CPU 대전은 직접 선택 · 2P는 매 판 새 맵</p><MapPicker :selected="selectedMap" @select="emit('chooseMap',$event)"/></section></section>
  <template v-if="(screen==='menu'||screen==='modes')&&localTab==='play'">
   <div class="hub-dashboard">
    <section class="hub-workbench" aria-label="새 게임 준비"><div class="hub-section-heading"><div><span class="hub-overline">LET'S PLAY</span><h2>어떤 배틀을 해볼까요?</h2></div><span class="hub-live"><i/> READY</span></div><div class="hub-mode-tabs" role="group" aria-label="게임 모드 선택"><button v-for="mode in orderedModes" :key="mode.id" :data-mode="mode.id" :aria-pressed="selectedMode===mode.id" :class="mode.id" @click="selectedMode=mode.id"><span class="hub-tab-icon"><HubIcon :name="mode.id==='item'?'spark':mode.id==='speed'?'bolt':'blocks'"/></span><span><strong>{{ mode.name }}</strong><small>{{ mode.id==='item'?'아이템으로 반전':mode.id==='speed'?'점점 빨라지는 승부':'익숙한 클래식 대전' }}</small></span><i>{{ selectedMode===mode.id?'✓':'' }}</i></button></div>
    <div class="hub-launcher"><section class="hub-preview" :class="selectedMode"><div class="hub-preview-top"><span>{{ classicName(selectedMode) }}</span><small>{{ hubStyle==='cpu'?'YOU vs CPU':'YOU & PLAYER 2' }}</small></div><div class="hub-preview-art"><ModePreview :variant="selectedMode"/></div><div class="hub-preview-copy"><span>{{ selectedMode==='item'?'A LITTLE SURPRISE':selectedMode==='speed'?'KEEP UP THE PACE':'GOOD OLD BATTLE' }}</span><h3>{{ selectedMode==='item'?'아이템 하나로,\n짜릿한 역전.':selectedMode==='speed'?'손끝이 빨라질수록,\n승부는 더 짜릿하게.':'차곡차곡 쌓고,\n시원하게 지워요.' }}</h3><p>{{ cardCopy(selectedMode).detail }}</p></div><div class="hub-preview-bottom"><span><HubIcon name="blocks"/>같은 블록 순서</span><span><HubIcon name="people"/>공정한 시작</span></div></section>
    <section class="hub-play-options"><h3><span>01</span> 누구와 플레이할까요?</h3><div class="hub-style-grid" role="group" aria-label="플레이 방식"><button v-for="option in hubStyles" :key="option.id" :aria-pressed="hubStyle===option.id" :disabled="option.id==='dual'&&!desktopKeyboard" @click="hubStyle=option.id"><HubIcon :name="option.icon"/><strong>{{ option.name }}</strong><small>{{ option.detail }}</small><b v-if="hubStyle===option.id">✓</b></button></div><div class="hub-round-info"><span class="hub-number">02</span><div><strong>{{ hubStyle==='cpu'?'내가 고른 맵에서':'매 판 새로운 맵으로' }}</strong><small>{{ hubStyle==='cpu'?mapNames[selectedMap]:'두 사람에게 같은 랜덤 맵이 적용돼요' }}</small></div><HubIcon name="blocks"/></div><button class="hub-start welcome-start" @click="emit('prepare',selectedMode,hubStyle)"><span>{{ hubStyle==='online'?'친구와 연결하기':`${modeName(selectedMode)} · 시작 준비` }}</span><HubIcon name="arrow"/></button><p class="hub-start-hint">맵과 규칙 확인 후 3 · 2 · 1, 시작!</p></section></div></section>
    <div class="hub-bottom-grid"><button class="hub-invite" aria-label="LAN · iPhone" @click="go('friends')"><span class="hub-invite-icon"><HubIcon name="online"/></span><span><small>PLAY TOGETHER</small><strong>같은 공간, 다른 화면.</strong><p>맥과 아이폰에서 초대 링크로 만나요.</p></span><HubIcon name="arrow"/></button><section class="hub-recent"><header><h2>최근 플레이</h2><button @click="go('stuff')">전체 보기 <span>↗</span></button></header><button v-for="recent in visibleRecent.slice(0,2)" :key="recent.mode" :data-recent="recent.mode" @click="emit('recent',recent)"><span class="hub-recent-icon"><HubIcon :name="recent.mode==='item'?'spark':recent.mode==='speed'?'bolt':'blocks'"/></span><span><strong>{{ modeName(recent.mode) }}</strong><small>{{ recent.network?'초대 대전':recent.cpu?'CPU':'같은 맥 2P' }} · {{ mapNames[recent.map] }}</small></span><HubIcon name="arrow"/></button><p v-if="!visibleRecent.length" class="hub-empty"><HubIcon name="clock"/>첫 게임을 시작하면 여기에 남아요.</p></section></div>
    <div class="hub-mini-stats" aria-label="이 기기 플레이 기록"><span><b>{{ totalGames }}</b>판 플레이</span><span><b>{{ totalWins }}</b>번의 승리</span><span>최고 점수 <b>{{ bestScore.toLocaleString() }}</b></span></div>
   </div>
  </template>
  <template v-else-if="localTab==='play'||(screen!=='menu'&&screen!=='modes')">
   <div class="page-heading"><button class="back-link" @click="emit('menu')">← 플레이로</button><span class="eyebrow">{{ screen==='lobby'?'BETTER TOGETHER':'MAKE YOURSELF AT HOME' }}</span><h1>{{ screen==='lobby'?'함께하면 더 재밌죠.':'손에 익으면, 더 재밌게.' }}</h1><p>{{ screen==='lobby'?'같은 Wi-Fi에서 연결하거나, 인터넷 대전 주소에서 같은 방으로 만나요.':'작은 팁부터 아이템 사용법까지. 편하게 살펴보세요.' }}</p></div>
   <section v-if="screen==='lobby'" class="lobby">
    <div v-if="!roomCode" class="connection-grid"><section class="glass-card host-card"><span class="eyebrow">01 · HOST A GAME</span><h2>내가 방 만들기</h2><p>모드와 맵을 고르고, 같이할 사람을 초대해요.</p><label>내 이름<input v-model="playerName" aria-label="닉네임" maxlength="20" autocomplete="nickname" placeholder="Player"></label><label>오늘의 모드<select aria-label="대전 모드" v-model="selectedMode"><option v-for="mode in orderedModes" :key="mode.id" :value="mode.id">{{ mode.name }}</option></select></label><MapPicker :selected="selectedMap" @select="emit('chooseMap',$event)"/><MatchOptions v-model="matchRules" :mode="selectedMode"/><label class="check"><input type="checkbox" v-model="hostSpectator"><span>맥은 관전 · 아이폰끼리 플레이<small>아이폰 2대로 플레이할 때 선택하세요.</small></span></label><button class="primary" aria-label="방 만들기" @click="emit('connect','create')">방 만들기 <span>＋</span></button></section><section class="glass-card join-card"><span class="eyebrow">02 · JOIN THE FUN</span><h2>친구 방으로 들어가기</h2><p>초대 링크를 열거나<br>전달받은 6자리 코드를 입력하세요.</p><label>방 코드<input class="code-input" v-model="joinCode" aria-label="방 코드" inputmode="numeric" maxlength="6" placeholder="000000" @keydown.enter="joinCode.length===6&&emit('connect','join')"></label><button class="secondary" aria-label="방 참가" :disabled="!/^\d{6}$/.test(joinCode)" @click="emit('connect','join')">방 참가 <span>↗</span></button><div class="connection-note"><span>⌁</span><p>방을 연 맥은 게임이 끝날 때까지<br>앱을 실행해 두세요.</p></div></section></div>
    <div v-else class="room-layout"><section class="glass-card room"><span class="room-status"><i/> OUR LITTLE GAME ROOM</span><h2 :aria-label="`ROOM ${roomCode}`">{{ roomCode }}</h2><p class="room-caption">같은 방, 같은 즐거움.</p><div class="roster"><div v-for="peer in roomPeers" :key="peer.seat"><span>{{ hostSpectator&&peer.seat===0?'H':peer.seat+(hostSpectator?0:1) }}</span><strong>{{ peer.name }}</strong><small>{{ hostSpectator&&peer.seat===0?'관전':'연결됨 ✓' }}</small></div></div><MapPicker v-if="seat===0" :selected="selectedMap" @select="emit('chooseMap',$event)"/><MatchOptions v-if="seat===0" v-model="matchRules"/><p class="room-rules" aria-label="선택한 대전 규칙">{{ matchRulesLabel(matchRules) }}</p><button v-if="seat===0" class="primary" aria-label="대전 시작" :disabled="roomPeers.length<(hostSpectator?3:2)" @click="emit('startNetwork')">{{ roomPeers.length<(hostSpectator?3:2)?'플레이어를 기다리고 있어요':'준비됐어요, 대전 시작' }} <span>→</span></button><p v-else class="waiting-note">방장이 시작하면 바로 연결돼요.</p></section><section v-if="shareURL" class="glass-card invite"><span class="eyebrow">SAVE A SEAT FOR SOMEONE</span><h3>초대는, 가볍게.</h3><p>카메라로 QR을 스캔하거나<br>아래 초대 링크를 보내 주세요.</p><div class="qr-paper"><img v-if="qr" :src="qr" alt="아이폰 참가 QR 코드"><small>SCAN & PLAY</small></div><input ref="inviteField" :value="shareURL" readonly aria-label="아이폰 접속 주소" @focus="($event.target as HTMLInputElement).select()"><div class="invite-actions"><button class="secondary" aria-label="초대 링크 복사" :disabled="sharing" @click="copyLink">링크 복사</button><button class="primary" aria-label="초대 링크 공유" :disabled="sharing" @click="shareLink">공유 ↗</button></div><p class="invite-status" role="status">{{ inviteStatus }}</p></section></div><p role="status" class="network-status">{{ networkError }}</p>
   </section>
   <section v-else class="guide-grid"><article class="glass-card guide-keyboard"><span class="eyebrow">01 · KEYBOARD</span><h2>손에 익은 키로.</h2><dl><dt>이동 / 천천히 낙하</dt><dd>← → / ↓</dd><dt>회전 / 반대 회전</dt><dd>↑ 또는 X / Z</dd><dt>빠른 낙하 / 홀드</dt><dd>Space / C</dd><dt>일시정지 / 전체 화면</dt><dd>P 또는 Esc / F</dd></dl><p>둘 다 같은 블록 순서로 진행해요.<br>선택한 KO 기준을 먼저 달성하면 승리!<br>시간 종료 시<br>원작: KO → 보낸 줄 → 낮은 블록 높이<br>자유 설정: KO → 보낸 줄 → 점수로 판정합니다.<br>키보드 두 개는 맥 앱 조작 설정에서<br>1P·2P 등록 후 같은 키 배치를 사용해요.</p><details><summary>한 키보드를 함께 쓸 때</summary><p>2P: A·D 이동 · W 회전 · S 낙하<br>Q 빠른 낙하 · E 홀드 · 아이템 R/T/Y</p></details></article><article class="glass-card guide-items"><span class="eyebrow">02 · A LITTLE SURPRISE</span><h2>아이템으로 한 번 더.</h2><dl><template v-for="item in ITEMS" :key="item.name"><dt>{{ item.icon }} {{ item.name }}</dt><dd>{{ item.description }}</dd></template></dl><p>아이템 V/B/N 또는 화면 버튼.<br>블록 속 아이템을 줄과 함께 지워 획득!<br>마지막 30초에는 아이템 블록이 더 자주 나와요.</p></article><article class="glass-card guide-touch"><span class="eyebrow">03 · TWO THUMBS</span><h2>두 엄지로, 빠르게.</h2><dl><dt>왼쪽 패드</dt><dd>좌우 이동 · 천천히 낙하</dd><dt>오른쪽 패드</dt><dd>회전 · 빠른 낙하</dd><dt>슬라이드</dt><dd>방향 버튼 사이를 끊김 없이</dd><dt>동시 입력</dt><dd>이동하면서 회전하기</dd></dl><p>조작 설정에서 크기·왼손 배치·속도를<br>내 손에 맞게 바꿀 수 있어요.</p></article></section>
  </template>
  <footer><span>즐거움은, 한 판 더. <b>✦</b></span><label><input type="checkbox" v-model="sound">음악</label></footer>
 </div>
</template>
<script setup lang="ts">
import HubIcon from './HubIcon.vue'
import {ITEMS} from '~/game/GameModes'
import MatchOptions from './MatchOptions.vue'
import {type MatchRules,matchRulesLabel} from '~/game/MatchRules'
import ModePreview from './ModePreview.vue'
import {MAP_OPTIONS} from '~/game/ClassicMaps'
import MapPicker from './MapPicker.vue'
import { ref,computed,watch } from 'vue'
import { type ModeId,type ModeInfo } from '~/game/GameModes'
import { type PlayerHistory,type RecentMode } from '~/game/PlayerHistory'
import { copyInviteLink,shareInviteLink } from '~/game/InviteLink'
const props=defineProps<{screen:string;modes:ModeInfo[];roomCode:string;roomPeers:{seat:number;name:string}[];seat:number;shareURL:string;qr:string;networkError:string;mapNames:string[];selectedMap:number;history:PlayerHistory;desktopKeyboard?:boolean;inputStyle?:string}>()
const matchRules=defineModel<MatchRules>('matchRules',{required:true})
const cpu=defineModel<boolean>('cpu',{required:true}),sound=defineModel<boolean>('sound',{required:true}),playerName=defineModel<string>('playerName',{required:true}),joinCode=defineModel<string>('joinCode',{required:true}),selectedMode=defineModel<ModeId>('selectedMode',{required:true}),hostSpectator=defineModel<boolean>('hostSpectator',{required:true})
const emit=defineEmits<{menu:[];modes:[];lobby:[];maps:[];help:[];quit:[];legacy:[];original:[];prepare:[mode:ModeId,style:'cpu'|'shared'|'dual'|'online'];select:[id:ModeId];chooseMap:[index:number];connect:[type:'create'|'join'];startNetwork:[];settings:[];profiles:[];recent:[item:RecentMode]}>()
const localTab=ref('play')
const hubStyle=ref<'cpu'|'shared'|'dual'|'online'>(cpu.value?'cpu':props.inputStyle==='dual'?'dual':'shared')
const hubStyles=[{id:'cpu' as const,name:'컴퓨터 대전',detail:'컴퓨터와 한 판',icon:'cpu'},{id:'shared' as const,name:'키보드 하나',detail:'나란히 앉아 2P',icon:'keyboard'},{id:'dual' as const,name:'각자 키보드',detail:'맥 앱 · 키보드 2개',icon:'people'},{id:'online' as const,name:'각자 화면',detail:'맥 · 아이폰 연결',icon:'online'}]
watch(cpu,value=>hubStyle.value=value?'cpu':props.inputStyle==='dual'?'dual':'shared')
function go(page:'play'|'friends'|'stuff'|'help'){if(page==='friends'){localTab.value='play';emit('lobby')}else if(page==='help'){localTab.value='play';emit('help')}else{localTab.value=page==='stuff'?'stuff':'play';emit('menu')}}
const bestScore=computed(()=>Math.max(0,...props.modes.map(m=>props.history.records[m.id]?.bestScore||0)))
const classicName=(id:ModeId)=>id==='speed'?'SPEED 2P':id==='item'?'ITEM BATTLE':'BATTLE 2P'
watch(()=>props.screen,()=>{if(props.screen!=='menu')localTab.value='play'})
const visibleRecent=computed(()=>props.history.recent.filter(r=>props.modes.some(m=>m.id===r.mode)))
const totalGames=computed(()=>props.modes.reduce((n,m)=>n+(props.history.records[m.id]?.games||0),0)),totalWins=computed(()=>props.modes.reduce((n,m)=>n+(props.history.records[m.id]?.wins||0),0))
const orderedModes=computed(()=>[...props.modes].sort((a,b)=>['battle2p','speed','item'].indexOf(a.id)-['battle2p','speed','item'].indexOf(b.id)))
const cardCopy=(id:ModeId)=>id==='item'?{tag:'PARTY',icon:'✦',copy:'아이템 하나로, 짜릿한 역전.',detail:'자동 부스트 / 블록 수집 선택'}:id==='speed'?{tag:'SPEED',icon:'ϟ',copy:'점점 빨라지는 짜릿한 승부.',detail:'15초마다 가속 · 8단계'}:{tag:'CLASSIC',icon:'▦',copy:'익숙해서 더 재밌는 기본 한 판.',detail:'시간 · KO · 선승제 직접 설정'}
const modeName=(id:ModeId)=>props.modes.find(m=>m.id===id)?.name||id
const inviteField=ref<HTMLInputElement|null>(null),inviteStatus=ref(''),sharing=ref(false)
watch(()=>props.shareURL,()=>inviteStatus.value='')
function manualCopy(){inviteField.value?.focus();inviteField.value?.select();inviteStatus.value='주소를 선택했어요. 길게 눌러 복사해 주세요.'}
async function copyLink(){sharing.value=true;try{if(await copyInviteLink(props.shareURL))inviteStatus.value='링크를 복사했어요.';else manualCopy()}finally{sharing.value=false}}
